import { useEffect, useState } from 'react';
import { getProfile } from '../api/auth';
import axios from '../api/axios';

export default function HomePage() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [procedures, setProcedures] = useState([]);
  const [futureAppointments, setFutureAppointments] = useState([]);
  const [pastAppointments, setPastAppointments] = useState([]);
  const [sortBy, setSortBy] = useState('timeAsc'); // timeAsc, timeDesc, priceAsc, priceDesc
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    getProfile()
      .then(res => {
        setUser(res.data);

        axios.get('/appointments/')
          .then(r => {
            const now = new Date();
            const future = r.data.filter(a => new Date(a.startUtc) > now);
            const past = r.data.filter(a => new Date(a.startUtc) <= now);
            setFutureAppointments(future);
            setPastAppointments(past);
          })
          .catch(err => console.error('Ошибка загрузки записей:', err));
      })
      .catch(() => setUser(null))
      .finally(() => setLoading(false));

    axios.get('/procedures')
      .then(res => setProcedures(res.data))
      .catch(err => console.error('Ошибка загрузки процедур:', err));
  }, []);

  // фильтрация и сортировка
  const filteredFuture = futureAppointments
    .filter(a => a.procedureId?.name.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => {
      if (sortBy === 'timeAsc') return new Date(a.startUtc) - new Date(b.startUtc);
      if (sortBy === 'timeDesc') return new Date(b.startUtc) - new Date(a.startUtc);
      if (sortBy === 'priceAsc') return a.procedureId?.price - b.procedureId?.price;
      if (sortBy === 'priceDesc') return b.procedureId?.price - a.procedureId?.price;
      return 0;
    });

  const filteredPast = pastAppointments
    .filter(a => a.procedureId?.name.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => new Date(b.startUtc) - new Date(a.startUtc)); // прошедшие по убыванию времени

  return (
    <main className="container section fade-in">
      <h1 className="h1">Добро пожаловать!</h1>
      <div className="grid">
        {/* профиль */}
        <article className="card card--half">
          <h2 className="h2">Профиль</h2>
          {loading ? (
            <p className="muted">Загрузка...</p>
          ) : !user ? (
            <p className="muted">Войдите или зарегистрируйтесь</p>
          ) : (
            <div className="info-list">
              <div className="info-list__item">
                <span className="info-list__label">ФИО</span>
                <span>{user.fullName}</span>
              </div>
              <div className="info-list__item">
                <span className="info-list__label">Email</span>
                <span>{user.email}</span>
              </div>
              <div className="info-list__item">
                <span className="info-list__label">Роль</span>
                <span>{user.role}</span>
              </div>
            </div>
          )}
        </article>

        {/* действия */}
        <article className="card card--half">
          <h2 className="h2">Действия</h2>
          <div className="form__actions">
            <a className="btn" href="/appointments">Записаться</a>
            <a className="btn btn--ghost" href="/procedures">Процедуры</a>
          </div>
        </article>

        {/* процедуры */}
        <article className="card card--full">
          <h2 className="h2">Доступные процедуры</h2>
          {procedures.length === 0 ? (
            <p className="muted">Нет доступных процедур</p>
          ) : (
            <ul className="info-list">
              {procedures.map(p => (
                <li key={p._id} className="info-list__item">
                  <span className="info-list__label">{p.name}</span>
                  <span>{p.price} ₽ / {p.durationMin} мин</span>
                </li>
              ))}
            </ul>
          )}
        </article>

        {/* записи клиента */}
        {user && (
          <article className="card card--full">
            <h2 className="h2">Мои записи</h2>

            {/* панель управления */}
            <div className="form__actions">
              <input
                type="text"
                placeholder="Поиск по названию процедуры..."
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
              <select value={sortBy} onChange={e => setSortBy(e.target.value)}>
                <option value="timeAsc">По времени (возрастание)</option>
                <option value="timeDesc">По времени (убывание)</option>
                <option value="priceAsc">По цене (возрастание)</option>
                <option value="priceDesc">По цене (убывание)</option>
              </select>
            </div>

            {/* будущие */}
            <h3 className="h3">Запланированные</h3>
            {filteredFuture.length === 0 ? (
              <p className="muted">Нет запланированных записей</p>
            ) : (
              <ul className="info-list">
                {filteredFuture.map(a => (
                  <li key={a._id} className="info-list__item" style={{ backgroundColor: '#e6f7ff' }}>
                    <div><strong>Клиент:</strong> {a.clientId?.fullName} ({a.clientId?.email})</div>
                    <div><strong>Процедура:</strong> {a.procedureId?.name}</div>
                    <div><strong>Цена:</strong> {a.procedureId?.price} ₽</div>
                    <div><strong>Дата:</strong> {new Date(a.startUtc).toLocaleString()}</div>
                    <div><strong>Статус:</strong> {a.status || 'scheduled'}</div>
                    {a.notes && <div><strong>Заметки:</strong> {a.notes}</div>}
                  </li>
                ))}
              </ul>
            )}

            {/* прошедшие */}
            <h3 className="h3">Завершённые</h3>
            {filteredPast.length === 0 ? (
              <p className="muted">Нет завершённых записей</p>
            ) : (
              <ul className="info-list">
                {filteredPast.map(a => (
                  <li key={a._id} className="info-list__item">
                    <div><strong>Клиент:</strong> {a.clientId?.fullName} ({a.clientId?.email})</div>
                    <div><strong>Процедура:</strong> {a.procedureId?.name}</div>
                    <div><strong>Цена:</strong> {a.procedureId?.price} ₽</div>
                    <div><strong>Дата:</strong> {new Date(a.startUtc).toLocaleString()}</div>
                    <div><strong>Статус:</strong> {a.status || 'completed'}</div>
                    {a.notes && <div><strong>Заметки:</strong> {a.notes}</div>}
                  </li>
                ))}
              </ul>
            )}
          </article>
        )}
      </div>
    </main>
  );
}
